mapper.select:
select
    dp.d_name as erDepartmentName,
    mn.*
from Expense_Reimbursement mn
left join Sys_Department dp on dp.d_id=mn.Er_Department

    
        and mn.er_Category = #{params.erCategory}
    
    
        and mn.state = #{params.state}
    
    
        and mn.create_Uid = #{params.createUid}
    
    
        and mn.er_Department = #{params.erDepartment}
    
    
        and mn.create_uname like concat('%',#{params.createUname},'%')
    
    
        and mn.er_Applicantr like concat('%',#{params.erApplicantr},'%')
    
    
        and dp.d_name like concat('%',#{params.erDepartmentName},'%')
    
    
        and mn.er_code like concat('%',#{params.erCode},'%')
    


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.Create_Time DESC
